head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > M > setTitle]<br/>Textarea 컴포넌트의 title 속성을 설정합니다.",
    "validation" : [
        "title(필수) 파라미터로 title 속성값을 문자열로 설정할 수 있어야 합니다.",
        "title 속성이 설정된 후 컴포넌트에 마우스를 올리면 설정된 title 값이 툴팁으로 표시되어야 합니다.",
        "title, tooltip 속성이 동시에 설정되면 툴팁이 중복 표시되어야 합니다.",
        "getTitle 메소드로 설정된 title 값을 조회할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="setTitle 실행 후 Textarea 에 마우스를 올려 툴팁 표시 확인"', '', 'label1');

    // textarea 생성 (초기 title 없음)
    await $c.gcm.createBasicTextArea();
}



scwin.btn_setTitle_onclick = function (e) {
    target1.setTitle(par_title.getValue());
};



scwin.btn_setTitleWithTooltip_onclick = async function (e) {
    // title, tooltip 동시 설정 시 툴팁 중복 표시 확인을 위해 tooltip 속성을 가진 textarea 재생성 후 setTitle 호출
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        tooltip: par_tooltip.getValue(),
    };

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicTextArea(cList);
    target1.setTitle(par_title.getValue());
};



scwin.btn_getTitle_onclick = function (e) {
    let rtn = target1.getTitle();
    wf_body_bottom.getObj("scwin").setReturnValue("getTitle : " + rtn);
};



scwin.btn_getDomTitle_onclick = function (e) {
    // DOM 의 실제 title 속성 확인
    let dom = document.querySelector('textarea[id*="target1"]');
    let domTitle = dom ? (dom.getAttribute("title") || "") : "";
    wf_body_bottom.getObj("scwin").setReturnValue("DOM title : '" + domTitle + "'");
};
